{
  "subtype": "faceted_decomposition",
  "concept": "agent_workload_burden",
  "per_column": [
    {
      "name": "issue_category",
      "is_constitutive_facet": false,
      "role": "external_predictor",
      "rationale": "The type of issue (email, VPN, hardware) is a characteristic of the ticket that may drive workload, but it is not itself an aspect OF the burden. It is an antecedent/predictor of how much effort is required, not a part of the effort concept."
    },
    {
      "name": "ticket_scope",
      "is_constitutive_facet": false,
      "role": "external_predictor",
      "rationale": "Scope (system-wide vs user-specific) is a property of the incident's blast radius that likely correlates with workload, but it describes the problem's reach, not a constitutive component of the agent's workload burden itself."
    },
    {
      "name": "recurrence_pattern",
      "is_constitutive_facet": false,
      "role": "external_predictor",
      "rationale": "Whether an issue recurs is a temporal/behavioral attribute of the problem that may generate more work, but recurrence is a cause/driver of burden, not a facet (part) of the burden concept."
    },
    {
      "name": "self_closure_vs_handoff",
      "is_constitutive_facet": false,
      "role": "external_predictor",
      "rationale": "Handoff vs self-closure is a process/routing indicator that may signal coordination effort, but it is a proxy/predictor of effort rather than a constitutive aspect of workload burden (e.g., time spent, touches, complexity)."
    }
  ],
  "facet_columns": [],
  "non_facet_columns": ["issue_category", "ticket_scope", "recurrence_pattern", "self_closure_vs_handoff"],
  "mutual_exclusivity": 0.0,
  "exhaustiveness": 0.0,
  "rationale": "None of the added columns are constitutive facets (parts) of 'agent_workload_burden'. Genuine facets would decompose the burden into its constitutive aspects such as time/effort expended (handling time, active work minutes), interaction volume (number of touches, reassignments, reopens), cognitive/technical complexity of resolution, and required collaboration/escalation load. Instead, every column is an external attribute of the ticket (issue type, scope, recurrence, closure routing) that serves as a PREDICTOR or DRIVER of workload rather than an aspect OF it. Because there are zero true facets, mutual exclusivity and exhaustiveness against the concept are both 0."
}

